/**
 * Embedded-canvas URL assembly for the `canvas-link` command.
 *
 * The CLI decorates the canonical canvas URL (returned by the backend) into a
 * tokenized link an agent opens inside an embedded browser: the single-use
 * handoff code rides the URL *fragment* (`#eh=<code>`) so it never reaches any
 * server access log. The fragment MUST come after all query params.
 */
/** Append defined query params, respecting an existing query string. */
export declare function appendQueryParams(url: string, params: Record<string, string | undefined>): string;
/**
 * Build the tokenized embedded-canvas URL from a canonical canvas URL and a
 * fresh single-use handoff code:
 *
 *   `<canvasUrl>?embed=1&live=1#eh=<code>`
 *
 * The `#eh=` fragment is appended AFTER all query params on purpose — a URL
 * fragment is never transmitted to the server, so the single-use code stays out
 * of every access log. `embed=1` and `live=1` are non-sensitive flags that put
 * the canvas into embedded mode and auto-connect the live stream.
 */
export declare function buildEmbedCanvasUrl(canvasUrl: string, code: string): string;
